/**
 * The transaction meta of tx efb32c1f as Stellar Expert serves it
 * (`/explorer/public/tx/<hash>`, field `meta`): a v4 TransactionMeta, trimmed to
 * its operation's token `transfer` events (11 of the 27 events; ledger changes,
 * pool trade events and diagnostics dropped). The last event pays 1608622 XAUM
 * base units (0.001608622) from the router to the swapper.
 */
export const usdcToXaumMeta =
  "";

type MetaWire = ReturnType<xdr.TransactionMeta["toXdrObject"]>;
type V4Wire = Extract<MetaWire, { v: 4 }>["v4"];
type EventWire = V4Wire["operations"][number]["events"][number];

/** An account other than the swapper, for a transfer that is not the viewer's. */
export const OTHER_ACCOUNT =
  "GBRPYHIL2CI3FNQ4BXLFMNDLFJUNPU2HY3ZMFSHONUCEOASW7QC7OX2H";

/** The decoded v4 meta of `usdcToXaumMeta`. */
export const realV4 = (): V4Wire => {
  const wire = xdr.TransactionMeta.fromXDR(
    usdcToXaumMeta,
    "base64",
  ).toXdrObject();
  if (wire.v !== 4) throw new Error("the fixture is a v4 meta");

  return wire.v4;
};

/** `usdcToXaumMeta` with its last event (the XAUM transfer from the router to the swapper) edited. */
export const withLastEvent = (
  edit: (event: EventWire) => EventWire,
): string => {
  const v4 = realV4();
  const [{ events }] = v4.operations;
  events[events.length - 1] = edit(events[events.length - 1]);

  return xdr.TransactionMeta.fromXdrObject({ v: 4, v4 }).toXDR("base64");
};

/** `usdcToXaumMeta` rewritten as a v3 meta, whose events sit on its Soroban meta. */
export const asV3 = (): string => {
  const v4 = realV4();

  return xdr.TransactionMeta.fromXdrObject({
    v: 3,
    v3: {
      ext: v4.ext,
      txChangesBefore: [],
      operations: [{ changes: [] }],
      txChangesAfter: [],
      sorobanMeta: {
        ext: { v: 0 },
        events: v4.operations[0].events,
        returnValue: nativeToScVal(null).toXdrObject(),
        diagnosticEvents: [],
      },
    },
  }).toXDR("base64");
};
